// PostToolUse hook (Write|Edit): type-check api/ after a file under api/src changes.
// Exit code 2 sends the compiler output back to Claude so it fixes the error right away.
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import path from 'node:path';

const MAX_OUTPUT_CHARS = 4000;

const input = JSON.parse(readFileSync(0, 'utf8'));
const editedFile = input.tool_input?.file_path ?? '';
const apiRoot = path.join(process.env.CLAUDE_PROJECT_DIR ?? process.cwd(), 'api');
const apiSource = path.join(apiRoot, 'src').toLowerCase();

if (!path.resolve(editedFile).toLowerCase().startsWith(apiSource)) {
  process.exit(0);
}

const result = spawnSync('pnpm', ['run', '--silent', 'typecheck'], { cwd: apiRoot, encoding: 'utf8', shell: true });

if (result.status !== 0) {
  const output = `${result.stdout}${result.stderr}`.slice(0, MAX_OUTPUT_CHARS);
  console.error(`Type errors in api/ after editing ${editedFile}:\n${output}`);
  process.exit(2);
}

// SessionStart hook: tell Claude when the local test database container is not running.
// Anything printed to stdout is added to the session context.
import { spawnSync } from 'node:child_process';

const CONTAINER_NAME = 'fieldly-test-db';

const result = spawnSync(
  'docker',
  ['ps', '--filter', `name=${CONTAINER_NAME}`, '--filter', 'status=running', '--format', '{{.Names}}'],
  { encoding: 'utf8' },
);

if (result.status !== 0 || !result.stdout.includes(CONTAINER_NAME)) {
  console.log(
    `The test database container "${CONTAINER_NAME}" is not running. Start Docker Desktop, then run: docker start ${CONTAINER_NAME}. ` +
      'Tests need FIELDLY_TEST_DATABASE_URL (postgresql://postgres:postgres@127.0.0.1:55432/postgres).',
  );
}

