import { createRequire } from 'node:module';
const require = createRequire('<project>/api/src/index.js');
const lib = require('libphonenumber-js/max');
const parse = lib.default ?? lib.parsePhoneNumberFromString;
const { getCountries, getCountryCallingCode } = lib;
const shape = /^\+\d{1,15}$/;
const bad = [], unstable = [], short = new Set();
let changed = 0, total = 0;
function check(s) {
  if (!shape.test(s)) return;
  const p = parse(s);
  if (!p?.isValid()) return;
  total++;
  const n = p.number;
  if (!/^\+[0-9]{1,15}$/.test(n)) bad.push([s, n]);
  if (n !== s) changed++;
  if (n.startsWith('+886')) bad.push(['886', s, n]);
  if (!n.startsWith('+' + p.countryCallingCode)) bad.push(['cc', s, n]);
  const q = parse(n);
  if (!q?.isValid() || q.number !== n) unstable.push([s, n, q?.number]);
  if (n.length - 1 < 7) short.add(n);
}
const ccs = new Set(getCountries().map((c) => getCountryCallingCode(c)));
let seed = 12345;
const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
for (const cc of ccs) {
  for (let i = 0; i < 3000; i++) {
    const len = 2 + Math.floor(rnd() * Math.max(1, 15 - cc.length - 1));
    let d = '';
    for (let k = 0; k < len; k++) d += Math.floor(rnd() * 10);
    for (const pre of ['', '0', '15', '1', '9', '00', '044', '045']) check('+' + cc + pre + d);
  }
  for (let n = 0; n < 100000; n += 1) {
    const d = String(n);
    if (cc.length + d.length <= 7) { check('+' + cc + d); check('+' + cc + '0' + d); }
  }
}
console.log(JSON.stringify({ total, changed, badCount: bad.length, bad: bad.slice(0, 20), unstableCount: unstable.length, unstable: unstable.slice(0, 20), shortCount: short.size, shortSample: [...short].slice(0, 15) }, null, 1));
